import sys; sys.path.insert(0,'.')
from helpers import *
D=np.load('base_feats.npz'); y=D['y']; folds=np.load('folds.npy')
c11=D['cls11'].astype(np.float64); m11=D['mean11'].astype(np.float64)
def run(c, lam_cat, mode, p):
    pred=np.zeros(len(y),int)
    for f in range(5):
        tr=folds!=f
        Wt,b=ridge_fit(np.hstack([c11[tr],m11[tr]]),y[tr],lam_cat)
        A=Wt[:,:768]; B=Wt[:,768:]
        M=c*np.eye(768)+np.linalg.pinv(A)@(B-c*A)
        X=c11+m11@M.T
        if mode=='direct':
            pred[~tr]=np.argmax(X[~tr]@A.T+b,1)
        elif mode=='lda':
            W2,b2=lda_fit(X[tr],y[tr],p); pred[~tr]=np.argmax(X[~tr]@W2.T+b2,1)
        else:
            W2,b2=ridge_fit(X[tr],y[tr],p); pred[~tr]=np.argmax(X[~tr]@W2.T+b2,1)
    return (pred==y).mean()
for lam in [100,300]:
    for c in [1,2]:
        print(lam,c,'direct',run(c,lam,'direct',0),'lda.2',run(c,lam,'lda',0.2),'ridge100',run(c,lam,'ridge',100),flush=True)
